def load() -> pd.DataFrame:
    import glob
    files = glob.glob('data/environment/input/monthly_precipitations_*.csv')
    dfs = []
    for file in sorted(files):
        df = pd.read_csv(file)
        dfs.append(df)
    return pd.concat(dfs, ignore_index=True)

def process(beaches_in_least_rainfall_city) -> pd.DataFrame:
    df = beaches_in_least_rainfall_city.copy()

    pollution_score = df.groupby('Beach Name').agg({
        'Violation': lambda x: (x == 'yes').sum(),
        'Indicator Level': 'mean'
    }).reset_index()

    pollution_score['pollution_rank'] = (
        pollution_score['Violation'] * 100 + pollution_score['Indicator Level']
    )

    top_3 = pollution_score.nlargest(3, 'pollution_rank')[['Beach Name', 'Violation', 'Indicator Level', 'pollution_rank']]
    return top_3

def process(load_beach_testing, identify_least_rainfall_city) -> pd.DataFrame:
    beaches = load_beach_testing
    least_rain_city = identify_least_rainfall_city

    target_city = least_rain_city['city'].iloc[0]

    unique_communities = beaches['Community'].unique()

    return pd.DataFrame({
        'target_city': [target_city],
        'target_city_in_communities': [target_city in unique_communities],
        'sample_communities': [', '.join(sorted(unique_communities)[:10])]
    })

def process(most_polluted_beaches):
    result = most_polluted_beaches.sort_values('pollution_rank', ascending=False)
    beach_names = result['Beach Name'].tolist()
    return pd.DataFrame({'Beach Name': beach_names})
